package in.kabadiwala.connect.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e){var d=new HashMap<String,String>();e.getBindingResult().getFieldErrors().forEach(x->d.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("success",false,"errorCode","VALIDATION_ERROR","message","Please check the entered information","details",d,"timestamp",Instant.now()));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("success",false,"errorCode","BUSINESS_RULE","message",e.getMessage(),"timestamp",Instant.now()));} @ExceptionHandler(Exception.class) ResponseEntity<?> all(Exception e){return ResponseEntity.status(500).body(Map.of("success",false,"errorCode","INTERNAL_ERROR","message","Something went wrong","timestamp",Instant.now()));} }
